func preimageSizeFZF(k int) int {
	f := func(x int) int {
		res := 0
		for x != 0 {
			x /= 5
			res += x
		}
		return res
	}

	g := func(k int) int {
		left, right := 0, k*5
		for left < right {
			mid := (left + right) >> 1
			if f(mid) >= k {
				right = mid
			} else {
				left = mid + 1
			}
		}
		return left
	}

	return g(k+1) - g(k)
}

class Solution(object):
    def preimageSizeFZF(self, k):
        """
        :type k: int
        :rtype: int
        """
        if k <= 1:
            return 5
        return self.f(k) - self.f(k - 1)

    def f(self, x):
        left, right = 0, 1e10
        while left < right:
            mid = (left + right + 1) // 2
            if self.get_cnt(mid) <= x:
                left = mid
            else:
                right = mid - 1
        return int(right)

    def get_cnt(self, x):
        ans = 0
        while x:
            x //= 5
            ans += x
        return ans
